	var isDownloading = false;

	/* 첨부파일 비동기 요청 */
	function fnDownAtchfileAsync(target, atchfileId, atchfileNm) {
	    var frm = document.atchfileForm;
	    frm.atchfileId.value = atchfileId;
	    frm.atchfileNm.value = atchfileNm;

	    if (isDownloading) {
			return;
	    }else if(!isDownloading){
	        toggleClick(target);
			startLoading();
	    }

		isDownloading = true;
		//파일 다운로드시 중복 요청 방지
        var form = $("form[name=atchfileForm]").serialize();

        var xhr = new XMLHttpRequest();
        xhr.open('POST', '/cs/CsDownAtchfile.do', true);
        xhr.responseType = 'blob';
        xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');

        xhr.onload = function() {
            if (this.status === 200) {	
                var blob = new Blob([this.response], { type: 'application/octet-stream' });

                var disposition = xhr.getResponseHeader('Content-Disposition');
                if (disposition && disposition.indexOf('attachment') !== -1) {
	             	var filename = atchfileNm;
                }else {
                	alert(msgBox('','조회하는데 실패하였습니다.'));
                }

             	// IE 대응 (msSaveBlob 사용)
                if (window.navigator && window.navigator.msSaveBlob) {
                    window.navigator.msSaveBlob(blob, filename);
                }else {
	                // 파일 다운로드
	                var url = window.URL.createObjectURL(blob);
	                var a = document.createElement('a');
	                a.href = url;
	                a.download = filename;

	             	// Safari에서 .txt가 붙는 것을 방지하기 위해 body에 잠시 추가
	                document.body.appendChild(a);
	                a.click();
	                window.URL.revokeObjectURL(url);
	                a.remove();
                }

                endLoading();
            	isDownloading = false;
       	        toggleClick(target);

            } else {
            	alert(msgBox('','조회하는데 실패하였습니다.'));
            }
        };
        xhr.send(form);
	}

	function startLoading(){
		$("#loading").show().fadeIn("fast");
	}

	function endLoading(){
		$("#loading").hide();
	}

	function toggleClick(target) {
		const $target = $(target);
	    const isDisabled = $target.css('pointer-events') === 'none';

	    $target.css({
	        'pointer-events': isDisabled ? 'auto' : 'none',
	        'cursor':         isDisabled ? 'pointer' : 'default',
	        'opacity':        isDisabled ? '1' : '0.5' // 처리 중임을 알리는 시각적 효과
	    });
	}

	function fileDownloader(fileUrl) {

	    var downloadLink = document.createElement('a');
	    downloadLink.href = fileUrl;

	    document.body.appendChild(downloadLink);
	    downloadLink.click();
	    document.body.removeChild(downloadLink);
	}

