	//두자 이상 특수 기호 방지
	function srchWorChk(obj){
	    var jobj = $("#"+obj);
	    if(jobj.val() != null)
	    {
	        if(jobj.val() == "검색어를 입력하세요." || trim(jobj.val())==""){
	            alert("검색어를 입력하세요.");
	            jobj.val("").focus();
